    "teamwork.level2.objective4": "Prepare e faça commit da solução mesclada",
    "teamwork.level2.hint1": "Use 'cat /src/auth/login.js' para ver suas alterações locais ainda não commitadas",
    "teamwork.level2.hint2": "Use 'git status' para confirmar que o arquivo foi modificado",
    "teamwork.level2.hint3": "Faça commit com 'git add /src/auth/login.js' e depois 'git commit -m \"message\"'",
    "teamwork.level2.hint4": "Faça pull com 'git pull origin main' — isso vai disparar o conflito!",
    "teamwork.level2.hint5": "Procure os marcadores de conflito: <<<<<<<, =======, >>>>>>>",
