    "archaeology.level1.hint2":
        "Adicione um intervalo de linhas como `git blame -L 10,20 src/utils/validator.js` para focar em uma parte do arquivo",
    "archaeology.level1.hint3":
        "Rode `git log --oneline` para ver um histórico compacto de todos os commits, cada um com um hash curto",
    "archaeology.level1.hint4":
        "Copie um hash de commit do log e rode `git show <hash>` (ou `git show HEAD`) para ver exatamente o que mudou",
    "archaeology.level1.requirement1.description":
        "Rode git blame em src/utils/validator.js para ver qual commit mudou por último cada linha",
    "archaeology.level1.requirement1.success": "Autoria do código revelada!",
    "archaeology.level1.requirement2.description": "Rode git log --oneline para ver um histórico compacto de commits",
    "archaeology.level1.requirement2.success": "Histórico recente examinado!",
    "archaeology.level1.requirement3.description":
        "Rode git show em um commit, por exemplo git show HEAD, para ver todos os detalhes",
